// The host's Vulkan loader (libvulkan.so.1), opened at run time (or ours,
// TODHCHAI_VULKAN_LIBRARY): it is the
// platform's interface to the GPU driver (architecture §18). Commands come
// through vkGetInstanceProcAddr and vkGetDeviceProcAddr into
// VulkanCommands (generated by vkgen).

import Glibc

/// The loader library and the commands loaded from it.
@safe public final class VulkanLibrary: @unchecked Sendable {
  let handle: UnsafeMutableRawPointer
  public let getInstanceProcAddr: PFN_vkGetInstanceProcAddr
  public var commands = VulkanCommands()

  public init() throws(VulkanError) {
    // The host's loader, or another named by TODHCHAI_VULKAN_LIBRARY (ours,
    // libtdvulkan.so: M5f).
    let path = unsafe getenv("TODHCHAI_VULKAN_LIBRARY").map { unsafe String(cString: $0) } ?? "libvulkan.so.1"
    guard let handle = unsafe dlopen(path, RTLD_NOW | RTLD_LOCAL) else { throw .noLoader }
    guard let symbol = unsafe dlsym(handle, "vkGetInstanceProcAddr") else {
      unsafe dlclose(handle)
      throw .noLoader
    }
    unsafe self.handle = unsafe handle
    unsafe getInstanceProcAddr = unsafe unsafeBitCast(symbol, to: PFN_vkGetInstanceProcAddr.self)
    unsafe commands.loadGlobal(getInstanceProcAddr)
  }

  deinit { unsafe dlclose(handle) }

  public func loadInstance(_ instance: VkInstance) { unsafe commands.loadInstance(getInstanceProcAddr, instance) }

  public func loadDevice(_ device: VkDevice) throws(VulkanError) {
    guard let get = unsafe commands.vkGetDeviceProcAddr else { throw .missing("vkGetDeviceProcAddr") }
    unsafe commands.loadDevice(get, device)
  }
}

